from collections import deque
def cc(g,color=None):
    H,W=len(g),len(g[0]); seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if seen[i][j]: continue
            c=g[i][j]
            if c==0: continue
            q=deque([(i,j)]); seen[i][j]=True; cs=[c]; pts=[]
            while q:
                x,y=q.popleft()
                pts.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx,ny=x+dx,y+dy
                    if 0<=nx<H and 0<=ny<W and not seen[nx][ny] and g[nx][ny]!=0 and (g[nx][ny]==c if color is not None else True):
                        seen[nx][ny]=True; q.append((nx,ny)); cs.append(g[nx][ny])
            rs=[p[0] for p in pts]; cl=[p[1] for p in pts]
            out.append(dict(color=c,n=len(pts),bbox=(min(rs),min(cl),max(rs),max(cl))))
    return out
