def report(k):
    gi=np.array(G[k+' input']); go=np.array(G[k+' output'])
    cnt=Counter(x for r in gi for x in r)
    cand={}
    for v,n in cnt.items():
        ps=[(i,j) for i in range(len(gi)) for j,x in enumerate(gi[i]) if x==v]
        rs={p[0] for p in ps}; cc={p[1] for p in ps}
        if len(rs)==2 and len(cc)==2:
            cand[v]=(min(rs),max(rs),min(cc),max(cc))
    # pick the most likely frame: try each and see which matches out shape; prefer one whose corner color differs from bg? demo6 both mk1&2 matched; choose frame matching out dims with largest area or marker!=bg. demo6 mk1 area bigger -> good. demo7/8 unique.
    best=max(cand.items(), key=lambda x: (x[1][1]-x[1][0]+1)*(x[1][3]-x[1][2]+1))
    mc,(r0,r1,c0,c1)=best
    sub=gi[r0:r1+1,c0:c1+1]; bg=int(sub[0][0])
    dd={(i,j):(int(sub[i][j]),int(go[i][j])) for i in range(sub.shape[0]) for j in range(sub.shape[1]) if sub[i][j]!=go[i][j]}
    print('===',k,'frame mk=',mc,(r0,r1,c0,c1),'bg',bg,'diffs:',dd)
    # sources: all non-bg, non-marker objects outside frame
    objs={}
    from collections import deque
    seen=set()
    for ci in range(len(gi)):
        for cj in range(len(gi[0])):
            col=gi[ci][cj]
            if col in (bg,mc): continue
            if (ci,cj) in seen: continue
            q=deque([(ci,cj)]); seen.add((ci,cj)); cells=[]
            while q:
                (a,b)=q.popleft(); cells.append((a,b))
                for da,db in ((-1,0),(1,0),(0,-1),(0,1)):
                    na,nb=a+da,b+db
                    if 0<=na<len(gi) and 0<=nb<len(gi[0]) and gi[na][nb]==col and (na,nb) not in seen:
                        seen.add((na,nb)); q.append((na,nb))
            inter=any(r0<=a<=r1 and c0<=b<=c1 for a,b in cells)
            a0=min(a for a,b in cells); b0=min(b for a,b in cells); a1=max(a for a,b in cells); b1=max(b for a,b in cells)
            objs.setdefault((color:=col),[]).append((len(cells),(a0,b0,a1,b1),inter))
    print('objs:',[(c_,info) for c_,info in objs.items()], 'in diff colors:',{v for v,*_ in dd.values()})
