    H,W=gi.shape; seen=set(); out=[]
    for i in range(H):
        for j in range(W):
            if gi[i,j]!=bg and (i,j) not in seen:
                c=int(gi[i,j]); st=[(i,j)]; seen.add((i,j)); cs=[]
                while st:
                    a,b=st.pop(); cs.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
